// pubspec.yaml:
//   camera: ^0.10.5+9
//   google_mlkit_text_recognition: ^0.13.0
import 'package:camera/camera.dart';
import 'package:google_mlkit_text_recognition/google_mlkit_text_recognition.dart';

class OCRScreen extends StatefulWidget {
  const OCRScreen({super.key});
  @override State<OCRScreen> createState() => _OCRScreenState();
}

class _OCRScreenState extends State<OCRScreen> {
  CameraController? _cam;
  final _ocr = TextRecognizer(script: TextRecognitionScript.latin);
  bool _busy = false;
  String _last = '';

  @override
  void initState() { super.initState(); _boot(); }

  Future<void> _boot() async {
    final cams = await availableCameras();
    _cam = CameraController(
      cams.firstWhere((c) => c.lensDirection == CameraLensDirection.back),
      ResolutionPreset.high, enableAudio: false,
      imageFormatGroup: Platform.isAndroid ? ImageFormatGroup.nv21 : ImageFormatGroup.bgra8888,
    );
    await _cam!.initialize();
    setState(() {});
    await _cam!.startImageStream(_onFrame);
  }

  Future<void> _onFrame(CameraImage img) async {
    if (_busy) return;   // drop frames while busy
    _busy = true;
    try {
      final input = InputImage.fromBytes(
        bytes: _concatenatePlanes(img.planes),
        metadata: InputImageMetadata(
          size: Size(img.width.toDouble(), img.height.toDouble()),
          rotation: InputImageRotation.rotation0deg,
          format: Platform.isAndroid ? InputImageFormat.nv21 : InputImageFormat.bgra8888,
          bytesPerRow: img.planes.first.bytesPerRow,
        ),
      );
      final result = await _ocr.processImage(input);
      if (result.text != _last) {
        _last = result.text;
        if (mounted) setState(() {});
      }
    } finally {
      _busy = false;
    }
  }

  Uint8List _concatenatePlanes(List<Plane> planes) {
    final all = <int>[];
    for (final p in planes) all.addAll(p.bytes);
    return Uint8List.fromList(all);
  }

  @override
  void dispose() {
    _cam?.stopImageStream().then((_) => _cam?.dispose());
    _ocr.close();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (_cam == null || !_cam!.value.isInitialized) return const CircularProgressIndicator();
    return Column(children: [
      Expanded(child: CameraPreview(_cam!)),
      Container(padding: const EdgeInsets.all(12), child: Text(_last)),
    ]);
  }
}
